import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.DtFQgA2F.js";const u=JSON.parse('{"title":"CG 项目管理器","description":"","frontmatter":{"title":"CG 项目管理器"},"headers":[],"relativePath":"tools/publisher.md","filePath":"tools/publisher.md","lastUpdated":1794984217000}'),d={name:"tools/publisher.md"};function o(l,e,n,c,p,r){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="cg-项目管理器" tabindex="-1">CG 项目管理器 <a class="header-anchor" href="#cg-项目管理器" aria-label="Permalink to &quot;CG 项目管理器&quot;">​</a></h1><p>终端界面小工具（C++20 + <a href="https://github.com/ArthurSonzogni/FTXUI" target="_blank" rel="noreferrer">FTXUI</a>）：一键把 <code>docs/</code> 里的 Markdown 笔记构建成 VitePress 站点并发布到 GitHub Pages。</p><ul><li>已编译程序：<code>tools/CG 项目管理器.exe</code></li><li>源码：<code>tools/publisher-cpp/</code>（<code>src/</code> 下 engine / cli / tui / main 四个模块）</li><li>配套脚本：<code>docs/scripts/publish-site.mjs</code>（构建产物铺到 <code>docs/</code> 根目录）</li></ul><h2 id="使用-终端界面" tabindex="-1">使用（终端界面） <a class="header-anchor" href="#使用-终端界面" aria-label="Permalink to &quot;使用（终端界面）&quot;">​</a></h2><ol><li>双击 <code>tools/CG 项目管理器.exe</code>，打开全屏终端界面</li><li>「仓库目录」自动检测（从 exe 所在目录向上找 <code>.git</code>），也可点「浏览…」手动选择</li><li>按需点击：</li></ol><table tabindex="0"><thead><tr><th>按钮</th><th>作用</th></tr></thead><tbody><tr><td>一键构建并发布</td><td>构建 → 发布 → 验证站点可访问，一条龙</td></tr><tr><td>构建站点</td><td>仅 <code>npm run docs:build</code></td></tr><tr><td>发布到 GitHub Pages</td><td>仅 git 暂存、提交、推送</td></tr><tr><td>打开站点</td><td>用浏览器打开 Pages 地址</td></tr><tr><td>清空日志</td><td>清空日志区</td></tr><tr><td>退出</td><td>关闭（也可直接按 Esc）</td></tr></tbody></table><p>底部状态栏显示 ✓/✗ 结果；日志区滚动输出命令结果（错误行红色），保留最近 25 行。构建/发布跑在工作线程，界面不卡顿。</p><h2 id="使用-cli" tabindex="-1">使用（CLI） <a class="header-anchor" href="#使用-cli" aria-label="Permalink to &quot;使用（CLI）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CG 项目管理器.exe --cli all                  # 构建 + 发布 + 验证（默认命令）</span></span>
<span class="line"><span>CG 项目管理器.exe --cli build                # 仅构建</span></span>
<span class="line"><span>CG 项目管理器.exe --cli publish              # 仅发布</span></span>
<span class="line"><span>CG 项目管理器.exe --cli open                 # 打开站点</span></span>
<span class="line"><span>CG 项目管理器.exe --cli all --repo E:\\Github\\CG   # 手动指定仓库路径</span></span></code></pre></div><ul><li>不带 <code>--repo</code> 时从 exe 所在目录向上自动找 <code>.git</code> 仓库根</li><li>退出码：<code>0</code> 成功 / <code>1</code> 流程失败 / <code>2</code> 参数或环境错误</li></ul><h2 id="重新编译发布器" tabindex="-1">重新编译发布器 <a class="header-anchor" href="#重新编译发布器" aria-label="Permalink to &quot;重新编译发布器&quot;">​</a></h2><p>改了 <code>tools/publisher-cpp/</code> 源码后（要求 VS 2022 Build Tools + CMake ≥ 3.24）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --preset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vs2022</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/vs2022</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/vs2022/Release/CG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 项目管理器.exe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/</span></span></code></pre></div><ul><li>FTXUI 由 FetchContent 在 configure 时自动下载，无需手动安装</li><li>依赖仅 Windows SDK（winhttp / shell32 / ole32），<strong>运行机器不需要任何运行时</strong>，单 exe 即用</li><li>⚠️ 若旧版发布器正在运行，exe 被占用无法覆盖——先关闭再复制</li></ul><h2 id="实现原理" tabindex="-1">实现原理 <a class="header-anchor" href="#实现原理" aria-label="Permalink to &quot;实现原理&quot;">​</a></h2><p>代码在 <code>tools/publisher-cpp/src/</code>，四个模块：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main.cpp ──┬── --cli 参数 ──&gt; cli.cpp（命令行模式）</span></span>
<span class="line"><span>           └── 无参数 ──────&gt; tui.cpp（FTXUI 终端界面）</span></span>
<span class="line"><span>                    共用 engine.cpp（构建/发布/验证流程引擎）</span></span></code></pre></div><ul><li><strong>engine</strong>：流程引擎，界面与 CLI 共用；通过 <code>LogFn</code> 回调把输出接到日志区或控制台 <ul><li><code>FindRepoRoot</code>：从起始目录向上找 <code>.git</code></li><li><code>RunCmd</code> / <code>CaptureCmd</code>：<code>CreateProcessW</code> + 管道逐行读取，命令前加 <code>chcp 65001</code> 保证 UTF-8 输出</li><li><code>ParseOwnerRepo</code>：兼容 <code>git@</code>、<code>ssh://</code>、<code>https://</code> 三种远端格式解析 owner/repo</li><li><code>SiteUrl</code>：区分项目页（<code>owner.github.io/repo/</code>）与用户页（<code>owner.github.io/</code>）</li><li><code>VerifyAsync</code>：WinHTTP 请求站点，200 即部署生效</li></ul></li><li><strong>cli</strong>：命令分发与退出码（0/1/2），<code>SetConsoleOutputCP(CP_UTF8)</code> 防中文乱码</li><li><strong>tui</strong>：FTXUI 组件树（输入框 + 按钮行 + 日志 Renderer），任务跑在 <code>std::thread</code>，日志入队后 <code>PostEvent(Event::Custom)</code> 触发重绘；共享状态用 <code>shared_ptr + mutex</code> 跨线程传递</li></ul><h3 id="构建流程-buildasync" tabindex="-1">构建流程（BuildAsync） <a class="header-anchor" href="#构建流程-buildasync" aria-label="Permalink to &quot;构建流程（BuildAsync）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检查 docs/ 存在 → node --version → 无 node_modules 则 npm install → npm run docs:build</span></span></code></pre></div><h3 id="发布流程-publishasync" tabindex="-1">发布流程（PublishAsync） <a class="header-anchor" href="#发布流程-publishasync" aria-label="Permalink to &quot;发布流程（PublishAsync）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检查 docs/index.html 存在</span></span>
<span class="line"><span>→ 保证 docs/.nojekyll（跳过 Jekyll，否则 .vitepress 等点开头目录 404）</span></span>
<span class="line"><span>→ git add docs + git add -f 强制加入被 .gitignore 忽略的产物</span></span>
<span class="line"><span>→ 无变更则跳过提交</span></span>
<span class="line"><span>→ 以 CGPublish 身份提交（deploy: CG 笔记站点 &lt;时间&gt;）</span></span>
<span class="line"><span>→ git push origin main</span></span></code></pre></div><blockquote><p>发布不拉取远端：直接使用本地构建产物提交并推送。若远端有新提交导致推送被拒绝，需先手动 <code>git pull --rebase</code> 再重试。</p></blockquote><h3 id="验证-verifyasync" tabindex="-1">验证（VerifyAsync） <a class="header-anchor" href="#验证-verifyasync" aria-label="Permalink to &quot;验证（VerifyAsync）&quot;">​</a></h3><p>HTTP GET 站点地址，返回 200 即部署生效；否则提示 Pages 部署中（约 1 分钟）。</p><h2 id="构建与部署链路" tabindex="-1">构建与部署链路 <a class="header-anchor" href="#构建与部署链路" aria-label="Permalink to &quot;构建与部署链路&quot;">​</a></h2><p><code>npm run docs:build</code> 由两步组成：</p><ol><li><code>vitepress build</code> —— 输出到 <code>docs/.vitepress/dist/</code></li><li><code>docs/scripts/publish-site.mjs</code> —— 清理上次产物后，把 <code>dist</code> 整目录复制到 <code>docs/</code> 根目录</li></ol><p><strong>为什么不能把 VitePress 的 outDir 直接设成 <code>docs/</code></strong>：VitePress 构建强制 emptyOutDir，会连源文件一起清空。所以先构建到中间目录，再复制过去。</p><p>发布器随后把被 <code>.gitignore</code> 忽略的产物（<code>docs/index.html</code>、<code>404.html</code>、<code>assets/</code>、<code>diagrams/</code>、<code>hashmap.json</code>、<code>notes/*.html</code>）force-add 提交并推送。<strong>GitHub Pages 直接部署 main 分支的 <code>/docs</code> 文件夹</strong>，推送后约 1 分钟自动生效。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因与处理</th></tr></thead><tbody><tr><td>推送被拒绝（远端有新提交）</td><td>本地历史落后远端：手动 <code>git pull --rebase</code> 处理后再发布</td></tr><tr><td>推送失败</td><td>SSH 密钥无该仓库写权限，检查 <code>~/.ssh</code></td></tr><tr><td>未找到 Node.js</td><td>安装 Node.js 并加入 PATH</td></tr><tr><td>依赖安装失败</td><td>npm install 网络问题，检查网络后重试</td></tr><tr><td>exe 无法覆盖</td><td>旧版发布器正在运行，先关闭</td></tr><tr><td>站点 404 / .vitepress 资源丢失</td><td><code>docs/.nojekyll</code> 缺失，发布器会自愈创建</td></tr></tbody></table>`,32)])])}const b=s(d,[["render",o]]);export{u as __pageData,b as default};
